import{_ as t,l as r,o as a,c as i,v as o,p as l,x as c,d as s,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"指针与别名","description":"","frontmatter":{"title":"指针与别名","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pointer-alias.md","filePath":"cs/pointer-alias.md","lastUpdated":1789023840000}'),h={name:"cs/pointer-alias.md"};function m(_,e,u,f,A,E){const d=r("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="指针与别名" tabindex="-1">指针与别名 <a class="header-anchor" href="#指针与别名" aria-label="Permalink to &quot;指针与别名&quot;">​</a></h1><div class="epigraph"><p>指针保存的是对象的地址；两个指针若指向同一对象，通过其中一个写入，另一个立刻看见——优化必须把这种可能算进去。</p><footer>—— 据 Kernighan &amp; Ritchie, The C Programming Language, 2nd ed.；ISO/IEC 9899；Bryant and O&#39;Hallaron, Computer Systems: A Programmer&#39;s Perspective 整理</footer></div><p>上一课<a href="/cs/stack-heap-static">栈、堆与静态存储</a>把三种寿命钉在三片区域上。本课不重讲 <code>malloc</code>，也不从类型论另起。缺口是：区域里的对象已经有名字，<strong>指针可以再制造跨作用域的名字</strong>。同一块存储多个视图时，读写通过谁发生？编译器何时不能假定「这两个指针绝不重叠」？</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>C 里指针是对象的地址值。<code>&amp;x</code> 取址，<code>*p</code> 解引用，指针赋值把同一视图交给别人。若 <code>p</code> 与 <code>q</code> 都指向 <code>x</code>，则 <code>*p = 1</code> 与 <code>*q = 2</code> 写的是同一存储。缺口因此不是 <code>*</code> 的语法，而是<strong>别名对语义与优化的约束</strong>：未声明 <code>restrict</code> 时，通过指针的写可能改掉「看似无关」的自动变量或全局。后课的未定义行为、悬挂，都先要承认「地址可以共享」。</p><p>传参默认按值：指针本身被拷贝，指向的对象不拷贝。这让 callee 能改 caller 的栈对象或堆块，而不必把结构体整份搬进帧。链表、树、输出参数都靠这一条。本课只钉「指向对象」；数组表达式为何常常变成指针，是<a href="/cs/array-decay">下一课</a>。</p><h3 id="指针不是整数" tabindex="-1">指针不是整数 <a class="header-anchor" href="#指针不是整数" aria-label="Permalink to &quot;指针不是整数&quot;">​</a></h3><p>调试时可以把地址印成整数，但指针算术与比较受对象类型和对象边界约束。把任意整数转换成指针再解引用，是<a href="/cs/undefined-behavior">未定义行为</a>的入口，不是「底层很自由」。本课语义里，指针首先是指向某个活着的对象，不是机器字上的无符号算术。</p><p><span class="marginnote">K&amp;R 用指针把数组、字符串与函数参数串起来。ISO C 的有效类型与别名规则约束「用哪种类型的左值去读这块存储」。CSAPP 把指针当地址，但立刻强调越界与类型错误会离开抽象机器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>int *p</code> 表示 <code>p</code> 保存某个 <code>int</code> 对象的地址，<code>*p</code> 是该对象的左值。指针参数把 caller 与 callee 绑到同一存储。<code>void *</code> 可以携带任意对象地址，但不携带类型；解引用前必须转回实际类型。空指针不指向任何对象，解引用它是 UB。</p>',11)),(a(),l(p,null,{default:c(()=>[n(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22%E5%AF%B9%E8%B1%A1%20x%22%5D%20--%3E%20P%5B%22p%20%E7%AD%89%E4%BA%8E%20x%20%E7%9A%84%E5%9C%B0%E5%9D%80%22%5D%0A%20%20P%20--%3E%20Q%5B%22q%20%E7%AD%89%E4%BA%8E%20p%22%5D%0A%20%20Q%20--%3E%20W%5B%22%E9%80%9A%E8%BF%87%20q%20%E5%86%99%E5%85%A5%22%5D%0A%20%20W%20--%3E%20X%0A"})]),fallback:c(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>两个指针是否别名，编译器在一般函数里无法静态看穿。于是它必须保守：不能把 <code>*p</code> 的旧值缓存过一次 <code>*q</code> 的写入。<code>restrict</code> 是程序员对「不重叠」的承诺，本课只点名，不把优化器内部展开。</p><p>函数若接受两个指针参数，文档必须声明它们是否允许重叠：<code>memcpy</code> 禁止，<code>memmove</code> 允许。这是别名写进契约的样板。实现可以用 <code>restrict</code> 让编译器按不重叠优化，一旦调用方违反，又是 UB。后课数组衰减会让 <code>int a[]</code> 与 <code>int *</code> 在参数上变成同一件事，别名分析看见的是指针，不是「数组对象不能重叠」的幻想。先把对象与指向它的指针分清，衰减才好讲。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>别名让「局部变量没人改」不再自动成立。一次通过指针的存储，可能让另一条看似无关的读必须重新从内存取。这不是编译器笨，是语言允许共享。反过来，若程序保证两路指针永不重叠，却不告诉编译器，就会留下本可去掉的 load。</p><p>堆上尤其如此：<code>malloc</code> 返回的地址进入多个指针变量之后，释放与再分配会让<strong>同一数值地址</strong>稍后属于另一个对象。别名是空间上的重叠；悬挂是时间上的错位。本课先把空间重叠钉死。</p><p>别名也解释了为何「看起来没人写的局部变量」在优化报告里仍被反复加载：只要存在一个可能指向它的指针参数，编译器就必须假定一次未知存储会改掉它。<code>restrict</code> 是把这个假定反过来写成程序员承诺，本课不把它当默认。结构体字段指针与数组元素指针都是同一机制的特例。后课未定义行为会把「用错类型的左值去读」也称为别名违规；这里先只要空间重叠这一层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开 strict aliasing 的逐条规则，也不讲整程序别名分析。数组与指针的互换见下一课。后课默认：指针表示活对象的地址；可能别名的指针限制优化；非法转换与空指针解引用属 UB。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指针保存地址；多指针可指向同一对象，写入立刻共享。</li><li>指针参数拷贝的是地址，不是对象；callee 能改 caller 的存储。</li><li>把指针当任意整数用会离开语言；<code>void *</code> 必须先恢复类型。</li><li>下一课处理数组在表达式里如何变成指针。</li><li>出处：K&amp;R；ISO C 有效类型；CSAPP 对指针即地址的程序员模型。</li></ul>',10))])}const g=t(h,[["render",m]]);export{q as __pageData,g as default};
